const outreach = $('Query Outreach KPIs').all().map(i => i.json);
const automation = $('Query Automation KPIs').all().map(i => i.json);

const latest = outreach[0] || {};
const prev = outreach[1] || {};

const report = [
  '# Weekly Pipeline Report',
  `Week of ${latest.week || 'N/A'}`,
  '',
  '## Outreach',
  `- Drafts: ${latest.drafts || 0} (prev: ${prev.drafts || 0})`,
  `- Sent: ${latest.sent || 0} (prev: ${prev.sent || 0})`,
  `- Responses: ${latest.responses || 0} (prev: ${prev.responses || 0})`,
  `- Response rate: ${(latest.response_rate * 100).toFixed(1)}%`,
  `- Negative rate: ${(latest.negative_rate * 100).toFixed(1)}%`,
  '',
  '## Automation',
].join('\n');

const autoLatest = automation[0] || {};
const reportFull = report + [
  `- Heartbeats: ${autoLatest.heartbeats || 0} (ok: ${autoLatest.heartbeats_ok || 0})`,
  `- Success rate: ${((autoLatest.heartbeat_success_rate || 0) * 100).toFixed(1)}%`,
  `- Override rate: ${((autoLatest.override_rate || 0) * 100).toFixed(1)}%`,
].join('\n');

return [{json: {report: reportFull, week: latest.week}}];
